#!/usr/bin/env bash
set -euo pipefail
ROOT=$(cd "$(dirname "$0")/.."&&pwd);IDMA=${IDMA_ROOT:-$ROOT/work/upstream/idma};VD=$IDMA/target/sim/vcs;OUT=${OUT:-$ROOT/work/results/qwen2_bias_rope_q1024_repeated};RUN=$ROOT/scripts/run_memory_capped.sh;mkdir -p "$OUT";MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$RUN" timeout --foreground --signal=INT --kill-after=30s 600s taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_canonical_tile16_vectors.py"|tee "$OUT/tile_vectors.log";MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$RUN" timeout --foreground --signal=INT --kill-after=30s 600s taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_canonical_q_tile16_all.py"|tee "$OUT/qkv_vectors.log";MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$RUN" timeout --foreground --signal=INT --kill-after=30s 600s taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_rope_q1024_repeated_vectors.py"|tee "$OUT/rope_vectors.log";taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_descriptor_macro_vectors.py" --packed-records "$ROOT/work/generated/qwen2_q1024_descriptor_image/packed_records.jsonl" --out "$OUT";taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_bias_context_vectors.py" --manifest "$ROOT/reports/execution/llama_cpp_qwen2_graph_lowering_manifest.jsonl" --chains "$ROOT/work/generated/qwen2_q1024_symbolic_descriptors/descriptor_chains.jsonl" --out "$OUT";taskset -c 8-23 python3 "$ROOT/scripts/generate_qwen2_rope_context_vectors.py" --manifest "$ROOT/reports/execution/llama_cpp_qwen2_graph_lowering_manifest.jsonl" --chains "$ROOT/work/generated/qwen2_q1024_symbolic_descriptors/descriptor_chains.jsonl" --out "$OUT"
cd "$VD";run(){ local limit=$1;shift;MIN_AVAILABLE_KIB=10485760 MEMORY_HIGH=24G MEMORY_MAX=30G "$RUN" timeout --foreground --signal=INT --kill-after=30s "$limit" taskset -c 8-23 "$@";};B=("$ROOT/work/generated/l5_all_primitives/HeteroAllPrimitives.sv" "$ROOT/rtl/sfu/bf16_bias_add_tile32.sv" "$ROOT/rtl/integration/qwen2_bias_descriptor_context.sv" "$ROOT/rtl/integration/qwen2_shared_l2_bias_payload.sv" "$ROOT/rtl/integration/qwen2_bias_tile16_controller.sv" "$ROOT/tb/tb_qwen2_bias_q1024_repeated.sv");R=("$ROOT/work/generated/l5_all_primitives/HeteroAllPrimitives.sv" "$ROOT/rtl/sfu/fp32_rope_pair.sv" "$ROOT/rtl/sfu/qwen2_rope_base_coeff64.sv" "$ROOT/rtl/sfu/qwen2_rope_base_coeff_q46.sv" "$ROOT/rtl/integration/qwen2_rope_descriptor_context.sv" "$ROOT/rtl/integration/qwen2_shared_l2_rope_payload.sv" "$ROOT/rtl/integration/qwen2_rope_tile16_controller.sv" "$ROOT/tb/tb_qwen2_rope_q1024_repeated.sv")
run 600s vlogan -sverilog -full64 -timescale=1ns/1ps +define+SYNTHESIS +incdir+"$ROOT" "${B[@]}" >"$OUT/bias_vlogan.log" 2>&1;run 600s vcs -full64 -top tb_qwen2_bias_q1024_repeated -o simv_bias1024 >"$OUT/bias_vcs.log" 2>&1;run 600s vlogan -sverilog -full64 -timescale=1ns/1ps +define+SYNTHESIS +incdir+"$ROOT" "${R[@]}" >"$OUT/rope_vlogan.log" 2>&1;run 600s vcs -full64 -top tb_qwen2_rope_q1024_repeated -o simv_rope1024 >"$OUT/rope_vcs.log" 2>&1
cd "$ROOT";for p in 0 1 2;do run 600s "$VD/simv_bias1024" +PROJECTION="$p" +COMMANDS="$OUT/bias_commands.memh" +RECORDS="$OUT/records.memh"|tee "$OUT/bias_p${p}.log";done;for p in 0 1;do run 600s "$VD/simv_rope1024" +PROJECTION="$p" +COMMANDS="$OUT/rope_commands.memh" +RECORDS="$OUT/records.memh"|tee "$OUT/rope_p${p}.log";done;grep -q 'QWEN2_BIAS_Q1024_REPEATED_PASS projection=0 batches=64' "$OUT/bias_p0.log";grep -q 'projection=1 batches=64' "$OUT/bias_p1.log";grep -q 'projection=2 batches=64' "$OUT/bias_p2.log";grep -q 'QWEN2_ROPE_Q1024_REPEATED_PASS projection=0 batches=64 positions=0_1023' "$OUT/rope_p0.log";grep -q 'projection=1 batches=64 positions=0_1023' "$OUT/rope_p1.log"
